const $=s=>document.querySelector(s),reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
let layerMode='3d',layerPlace=null,selectedFloor=null,sheetIndex=1;
const sheetStops=[22,44,74];
export function setSheet(index){sheetIndex=Math.max(0,Math.min(2,index));document.documentElement.style.setProperty('--clue-sheet',sheetStops[sheetIndex]+'dvh');const h=$('#sheetHandle');if(h){h.setAttribute('aria-expanded',String(sheetIndex===2));h.setAttribute('aria-valuenow',String(sheetIndex+1));}}
export function setupExperience({en,onResume,onDiscard,onFeedback}){
 const t=(zh,eng)=>en?eng:zh;document.body.classList.add('meeting-layout');
 $('[data-nav="find"]').textContent=t('推荐','Recommended');$('.brand').setAttribute('aria-label','Clue · '+t('推荐首页','Recommended home'));
 const feedback=document.createElement('button');feedback.id='globalFeedback';feedback.className='nav-feedback';feedback.textContent=t('反馈','Feedback');feedback.onclick=onFeedback;$('.topbar nav').append(feedback);
 const resume=document.createElement('section');resume.id='resumeTrail';resume.className='resume-trail';resume.hidden=true;resume.innerHTML=`<span class="resume-pin" aria-hidden="true">↳</span><div><strong>${t('上次的线索，还在这里','Your trail is still here')}</strong><small id="resumeTrailText"></small></div><button id="resumeDraft" class="primary">${t('继续查找','Continue')}</button><button id="discardDraft" class="text-button">${t('清除','Clear')}</button>`;$('.explorer-toolbar').before(resume);$('#resumeDraft').onclick=onResume;$('#discardDraft').onclick=onDiscard;
 const handle=document.createElement('button');handle.id='sheetHandle';handle.className='sheet-handle';handle.setAttribute('aria-label',t('调整线索面板高度；点击或按上下键，也可拖动','Resize clue panel: click, use arrow keys, or drag'));handle.innerHTML=`<span aria-hidden="true"></span><small>${t('线索面板 · 拖动或点击','CLUE SHEET · DRAG OR TAP')}</small>`;$('.clue-extension-column').prepend(handle);let drag=null,suppress=false;
 handle.onpointerdown=e=>{drag={y:e.clientY,h:sheetStops[sheetIndex]/100*innerHeight};handle.setPointerCapture(e.pointerId);};handle.onpointermove=e=>{if(!drag)return;const dy=drag.y-e.clientY;if(Math.abs(dy)>5)suppress=true;document.documentElement.style.setProperty('--clue-sheet',Math.max(innerHeight*.22,Math.min(innerHeight*.74,drag.h+dy))+'px');};handle.onpointerup=e=>{if(!drag)return;const ratio=(drag.h+drag.y-e.clientY)/innerHeight*100;drag=null;setSheet(sheetStops.reduce((best,v,i)=>Math.abs(v-ratio)<Math.abs(sheetStops[best]-ratio)?i:best,0));};handle.onpointercancel=()=>{drag=null;setSheet(sheetIndex);};handle.onclick=()=>{if(suppress){suppress=false;return;}setSheet((sheetIndex+1)%3);};handle.onkeydown=e=>{if(['ArrowUp','ArrowDown','Home','End'].includes(e.key)){e.preventDefault();setSheet(e.key==='Home'?0:e.key==='End'?2:sheetIndex+(e.key==='ArrowUp'?1:-1));}};setSheet(1);
 $('#indoorTab').textContent=t('楼层 / 3D','Floors / 3D');
}
export function refreshExperience({en,draft,place,guide,stage}){
 const t=(zh,eng)=>en?eng:zh;$('#resumeTrail').hidden=!draft||!!guide;const text=$('#resumeTrailText');if(draft)text.textContent=(en?draft.name:draft.zh)+' · '+t('步骤 ','Step ')+(draft.stage+1)+t(' · 仅保存在此浏览器',' · saved in this browser');
 $('#boardPage').classList.toggle('guiding',!!guide);document.body.classList.toggle('on-board',!$('#boardPage').hidden);
 if(guide){const heading=$('#guidePane .journey-stage');if(heading)heading.setAttribute('aria-label',t('当前步骤','Current step')+' '+(stage+1));}
 if(!place&&!guide&&$('#results').classList.contains('popular-results'))$('#listTitle').textContent=t('推荐线索 · 热门 Top 10','Recommended · Trending Top 10');
}
export function floorChoice(){return selectedFloor;}
export function enhanceIndoor({p,en,demo}){
 const container=$('#indoorMap');const back=document.createElement('button');back.id='returnCampus';back.className='floor-return';back.textContent=en?'← Campus map':'← 校园地图';back.onclick=()=>$('#outdoorTab').click();container.prepend(back);if(!p||!demo)return;const plan=container.querySelector('.floor-sketch'),caption=container.querySelector('.indoor-caption');if(!plan)return;
 const t=(zh,eng)=>en?eng:zh;if(layerPlace!==p.id){layerPlace=p.id;selectedFloor=p.floor||'G';layerMode='3d';}
 const levels=[...new Set(['G','UG','1','2','3','4',...(p.floor?[p.floor]:[])])];
 const ui=document.createElement('div');ui.className='floor-explorer';ui.innerHTML=`<div class="floor-view-controls"><div role="group" aria-label="${t('楼层显示方式','Floor display mode')}"><button data-floor-mode="3d">${t('立体分层','3D layers')}</button><button data-floor-mode="2d">${t('平面示意','2D sketch')}</button></div><label>${t('查看楼层','View floor')}<select id="floorSelect">${levels.map(f=>`<option value="${f}">${f}</option>`).join('')}</select></label></div><div class="floor-stack" id="floorStack" role="group" aria-label="${t('演示建筑分层；不是实际建筑模型','Illustrative building layers; not an actual building model')}">${levels.map((f,i)=>`<button class="floor-plate" style="--layer:${i}" data-floor="${f}" aria-label="${t('查看楼层','View floor')} ${f}"><span class="floor-number">${f}</span>${f===p.floor?`<span class="floor-target">● ${t('目标','Target')}</span>`:''}<i></i><i></i><i></i></button>`).join('')}</div><p class="floor-layer-note" id="floorLayerNote"></p><small class="floor-assumption">${t('楼层数量、轮廓和房间位置均为示意，不代表实际建筑。','Floor count, outlines and room positions are illustrative, not the actual building.')}</small>`;plan.before(ui);
 const draw=()=>{ui.querySelectorAll('[data-floor-mode]').forEach(b=>{const active=b.dataset.floorMode===layerMode;b.setAttribute('aria-pressed',String(active));});ui.querySelectorAll('[data-floor]').forEach(b=>{b.classList.toggle('active',b.dataset.floor===selectedFloor);b.setAttribute('aria-pressed',String(b.dataset.floor===selectedFloor));});$('#floorSelect').value=selectedFloor;$('#floorStack').hidden=layerMode!=='3d';plan.hidden=layerMode!=='2d'||selectedFloor!==p.floor;caption.hidden=plan.hidden;container.dataset.floorView=layerMode;$('#floorLayerNote').textContent=selectedFloor===p.floor?t('目标楼层：','Destination floor: ')+p.floor+' · '+(en?p.name:p.zh):t('当前查看：','Viewing floor: ')+selectedFloor+t('。目标位于 ','; destination is on ')+(p.floor||'?')+t(' 层。此层没有目标地点线索。','. No destination clue is shown on this floor.');};
 ui.querySelectorAll('[data-floor-mode]').forEach(b=>b.onclick=()=>{layerMode=b.dataset.floorMode;draw();});ui.querySelectorAll('[data-floor]').forEach(b=>b.onclick=()=>{selectedFloor=b.dataset.floor;draw();});$('#floorSelect').onchange=e=>{selectedFloor=e.target.value;draw();};draw();
}
export function focusGuide(){const file=$('.case-file');file.scrollTop=0;const heading=$('#guidePane h3');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}if(!reduced())$('#guidePane .journey-stage')?.animate([{opacity:.4,transform:'translateY(8px)'},{opacity:1,transform:'translateY(0)'}],{duration:220});}
